/**
 * Minimal & Embedded JSZip Implementation for in-browser .xdc (ZIP) creation
 * Supports raw deflate compression via CompressionStream / raw deflate bytes with fallback to STORE mode.
 * Fully offline, zero external dependencies.
 */
(function(global) {
  function Crc32Table() {
    let c;
    const table = new Uint32Array(256);
    for (let n = 0; n < 256; n++) {
      c = n;
      for (let k = 0; k < 8; k++) {
        if (c & 1) c = 0xedb88320 ^ (c >>> 1);
        else c = c >>> 1;
      }
      table[n] = c >>> 0;
    }
    return table;
  }

  const CRC_TABLE = Crc32Table();

  function crc32(buf) {
    let crc = (0 ^ (-1)) >>> 0;
    for (let i = 0; i < buf.length; i++) {
      crc = (crc >>> 8) ^ CRC_TABLE[(crc ^ buf[i]) & 0xff];
      crc = crc >>> 0;
    }
    return ((crc ^ (-1)) >>> 0);
  }

  function uint16ToBytes(val) {
    return [val & 0xff, (val >> 8) & 0xff];
  }

  function uint32ToBytes(val) {
    return [val & 0xff, (val >> 8) & 0xff, (val >> 16) & 0xff, (val >> 24) & 0xff];
  }

  function strToUint8(str) {
    if (typeof TextEncoder !== 'undefined') {
      return new TextEncoder().encode(str);
    }
    const buf = new Uint8Array(str.length);
    for (let i = 0; i < str.length; i++) {
      buf[i] = str.charCodeAt(i) & 0xff;
    }
    return buf;
  }

  // Compress using browser native 'deflate-raw' CompressionStream if available
  async function deflateBytes(dataBytes) {
    if (typeof CompressionStream !== 'undefined') {
      try {
        const cs = new CompressionStream('deflate-raw');
        const writer = cs.writable.getWriter();
        writer.write(dataBytes);
        writer.close();
        const response = new Response(cs.readable);
        const arrayBuf = await response.arrayBuffer();
        return new Uint8Array(arrayBuf);
      } catch (e) {
        // Some older engines support 'deflate' (zlib-wrapped), we strip 2 byte header and 4 byte Adler checksum
        try {
          const cs = new CompressionStream('deflate');
          const writer = cs.writable.getWriter();
          writer.write(dataBytes);
          writer.close();
          const response = new Response(cs.readable);
          const arrayBuf = await response.arrayBuffer();
          const zlibBytes = new Uint8Array(arrayBuf);
          if (zlibBytes.length > 6) {
            return zlibBytes.subarray(2, zlibBytes.length - 4);
          }
        } catch (e2) {
          // Fallback to uncompressed
        }
      }
    }
    return null;
  }

  class JSZip {
    constructor() {
      this.files = {};
    }

    file(name, content) {
      if (content === undefined) {
        return this.files[name] ? this.files[name].content : null;
      }
      let data;
      if (typeof content === 'string') {
        data = strToUint8(content);
      } else if (content instanceof Uint8Array) {
        data = content;
      } else if (content instanceof ArrayBuffer) {
        data = new Uint8Array(content);
      } else {
        data = strToUint8(JSON.stringify(content));
      }
      this.files[name] = {
        name: name,
        content: data,
        date: new Date()
      };
      return this;
    }

    async generateAsync(options = { type: 'blob', compression: 'DEFLATE' }) {
      const fileHeaders = [];
      const centralDirHeaders = [];
      let currentOffset = 0;

      const fileKeys = Object.keys(this.files);

      for (const key of fileKeys) {
        const file = this.files[key];
        const fileNameBytes = strToUint8(file.name);
        const dataBytes = file.content;
        const uncompressedSize = dataBytes.length;
        const fileCrc = crc32(dataBytes);

        let compressedBytes = null;
        if (options.compression === 'DEFLATE') {
          compressedBytes = await deflateBytes(dataBytes);
        }

        const isDeflated = !!compressedBytes && compressedBytes.length < uncompressedSize;
        const finalData = isDeflated ? compressedBytes : dataBytes;
        const compressedSize = finalData.length;
        const compressionMethod = isDeflated ? 0x08 : 0x00; // 8 = DEFLATE, 0 = STORE

        const d = file.date;
        const dosTime = ((d.getHours() << 11) | (d.getMinutes() << 5) | (d.getSeconds() >> 1)) & 0xffff;
        const dosDate = (((d.getFullYear() - 1980) << 9) | ((d.getMonth() + 1) << 5) | d.getDate()) & 0xffff;

        const localHeader = new Uint8Array([
          0x50, 0x4b, 0x03, 0x04,
          0x14, 0x00,
          0x00, 0x00,
          ...uint16ToBytes(compressionMethod),
          ...uint16ToBytes(dosTime),
          ...uint16ToBytes(dosDate),
          ...uint32ToBytes(fileCrc),
          ...uint32ToBytes(compressedSize),
          ...uint32ToBytes(uncompressedSize),
          ...uint16ToBytes(fileNameBytes.length),
          0x00, 0x00
        ]);

        const fullLocalEntry = new Uint8Array(localHeader.length + fileNameBytes.length + finalData.length);
        fullLocalEntry.set(localHeader, 0);
        fullLocalEntry.set(fileNameBytes, localHeader.length);
        fullLocalEntry.set(finalData, localHeader.length + fileNameBytes.length);
        fileHeaders.push(fullLocalEntry);

        const centralHeader = new Uint8Array([
          0x50, 0x4b, 0x01, 0x02,
          0x14, 0x00,
          0x14, 0x00,
          0x00, 0x00,
          ...uint16ToBytes(compressionMethod),
          ...uint16ToBytes(dosTime),
          ...uint16ToBytes(dosDate),
          ...uint32ToBytes(fileCrc),
          ...uint32ToBytes(compressedSize),
          ...uint32ToBytes(uncompressedSize),
          ...uint16ToBytes(fileNameBytes.length),
          0x00, 0x00,
          0x00, 0x00,
          0x00, 0x00,
          0x00, 0x00,
          0x00, 0x00, 0x00, 0x00,
          ...uint32ToBytes(currentOffset)
        ]);

        const fullCentralEntry = new Uint8Array(centralHeader.length + fileNameBytes.length);
        fullCentralEntry.set(centralHeader, 0);
        fullCentralEntry.set(fileNameBytes, centralHeader.length);
        centralDirHeaders.push(fullCentralEntry);

        currentOffset += fullLocalEntry.length;
      }

      const centralDirOffset = currentOffset;
      const centralDirSize = centralDirHeaders.reduce((acc, curr) => acc + curr.length, 0);
      const totalEntries = fileKeys.length;

      const eocd = new Uint8Array([
        0x50, 0x4b, 0x05, 0x06,
        0x00, 0x00,
        0x00, 0x00,
        ...uint16ToBytes(totalEntries),
        ...uint16ToBytes(totalEntries),
        ...uint32ToBytes(centralDirSize),
        ...uint32ToBytes(centralDirOffset),
        0x00, 0x00
      ]);

      const totalSize = currentOffset + centralDirSize + eocd.length;
      const finalZipBuffer = new Uint8Array(totalSize);

      let pos = 0;
      for (const entry of fileHeaders) {
        finalZipBuffer.set(entry, pos);
        pos += entry.length;
      }
      for (const entry of centralDirHeaders) {
        finalZipBuffer.set(entry, pos);
        pos += entry.length;
      }
      finalZipBuffer.set(eocd, pos);

      if (options.type === 'blob') {
        return new Blob([finalZipBuffer], { type: 'application/zip' });
      } else if (options.type === 'uint8array') {
        return finalZipBuffer;
      }
      return finalZipBuffer;
    }
  }

  global.JSZip = JSZip;
})(window);
